      note.className = 'plab-note good';
      note.textContent = `Error de prueba ${K.fmt(eTe / te.length, 3)} frente a ${K.fmt(eTr / tr.length, 3)} en entrenamiento.` +
        (key === 'big' ? ` El error de Bayes (${K.fmt(bayes, 3)}) es el mínimo posible; en esta muestra de prueba, el menor error de k-NN se alcanza con k = ${best[0]} (${K.fmt(best[2], 3)}). Ojo: elegir k mirando la prueba es hacer trampa; el capítulo de validación muestra cómo elegirlo sin tocarla.` : ' Con diez clientes, un solo caso cambia mucho el resultado.');
    }
  }

  root.querySelectorAll('input[type=range]').forEach(el => el.addEventListener('input', render));
  syncControls();
  render();
})();
</script>
